extends "res://htd/htd_test.gd"

var ruby_signal_val: int = 0
var ruby_received: bool = false


func _on_ruby(val: int) -> void:
	ruby_received = true
	ruby_signal_val = val


func _run_tests() -> void:
	var ruby := await instantiate_scene("res://ruby.tscn")
	if not check("ruby_scene", ruby != null, "ruby.tscn deve aprirsi senza errori"):
		return
	if not check("ruby_signal", ruby.has_signal("collected"), "Ruby deve avere il segnale 'collected'"):
		return
	if not check("ruby_collect", has_function(ruby, "collect"), "Ruby deve avere il metodo collect()"):
		return
	var expected_points = get_prop(ruby, "points", 150)
	ruby.collected.connect(_on_ruby)
	call_if_exists(ruby, "collect")
	check("signal_fired", ruby_received, "Chiamando collect() il segnale collected deve essere emesso")
	check("val_points", ruby_signal_val == expected_points, "Il segnale collected di Ruby deve trasmettere il valore di points (%s)" % str(expected_points))

extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve avviarsi"):
		return
	if not check("ruby_callback", has_function(main, "_on_ruby_collected"), "basket.gd deve avere la funzione _on_ruby_collected"):
		return
	var s_before: int = int(get_prop(main, "score", 0))
	call_if_exists(main, "_on_ruby_collected", [150])
	var s_after: int = int(get_prop(main, "score", 0))
	check("ruby_score", s_after == s_before + 150, "_on_ruby_collected deve sommare i punti ricevuti al punteggio")
